mapper.select:
 WHERE  AND c.sea_type=#{q.sea}
AND c.customer_name LIKE CONCAT('%',#{q.keyword},'%')
AND c.customer_status=#{q.customerStatus}
AND c.customer_level=#{q.customerLevel}
AND c.source_code=#{q.sourceCode}
AND c.industry_code=#{q.industryCode}
AND c.region LIKE CONCAT('%',#{q.region},'%')
AND c.owner_id=#{q.ownerId}
AND c.sea_type='PRIVATE' AND c.customer_status IN ('FOLLOWING','PROTECTED')
  AND u.account_status='ACTIVE' AND u.role_code IN ('MANAGER','SPECIALIST') AND u.team_id=c.team_id AND t.enabled=1

  AND (
    JSON_CONTAINS(COALESCE(c.tags_json,JSON_ARRAY()),JSON_QUOTE(#{tag}))

    JSON_CONTAINS(COALESCE(c.tags_json,JSON_ARRAY()),JSON_QUOTE(#{tag}))
  )

ORDER BY c.id DESC
